 void selectedRowsChanged(int row)override{selected=row;repaint();}void listBoxItemDoubleClicked(int row,const juce::MouseEvent&)override{if(row>=0&&row<getNumRows())p.loadPresetFile(visible[row].file);}
 void filter(){visible.clear();auto q=search.getText().trim();for(auto e:all)if((!favourites.getToggleState()||e.favourite)&&(q.isEmpty()||(e.name+" "+e.category+" "+e.tags).containsIgnoreCase(q)))visible.push_back(e);selected=-1;list.deselectAllRows();list.updateContent();repaint();}
 void choose(bool importing){chooser=std::make_unique<juce::FileChooser>(importing?"Importar sonido Nova Synth":"Exportar sonido elegido",juce::File{},"*.novapreset");auto safe=juce::Component::SafePointer<PersonalLibraryView>(this);auto chosen=selected>=0&&selected<getNumRows()?visible[selected].file:juce::File{};chooser->launchAsync(juce::FileBrowserComponent::canSelectFiles|(importing?juce::FileBrowserComponent::openMode:juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::warnAboutOverwriting),[safe,importing,chosen](const juce::FileChooser& dialog){if(!safe)return;auto f=dialog.getResult();if(f==juce::File{})return;if(importing){safe->p.importPersonal(f);safe->refresh();}else if(chosen!=juce::File{}){auto dest=f.withFileExtension("novapreset");safe->p.say(chosen==dest||chosen.copyFileTo(dest)?"Preset exportado.":"No se pudo exportar.");}});}
public:
 std::function<void()> onClose;juce::Colour accent{0xff40a9ff};explicit PersonalLibraryView(NovaProcessor& owner):p(owner){for(auto* c:std::initializer_list<juce::Component*>{&name,&category,&tags,&search,&list,&favourites,&pattern,&save,&load,&preview,&stop,&favourite,&import,&exportFile,&close,&refreshButton})addAndMakeVisible(c);name.setName("personalName");category.setName("personalCategory");tags.setName("personalTags");name.setInputRestrictions(80);category.setInputRestrictions(40);tags.setInputRestrictions(160);search.setTextToShowWhenEmpty("Buscar nombre, categoria o etiqueta",juce::Colour(0xffa3b7cc));category.setText("Personal");list.setRowHeight(50);list.setColour(juce::ListBox::backgroundColourId,juce::Colour(0xff0b1420));pattern.addItemList({"Nota","Acorde","Secuencia"},1);pattern.setSelectedId(1,juce::dontSendNotification);search.onTextChange=[this]{filter();};favourites.onClick=[this]{filter();};save.onClick=[this]{if(p.savePersonal(name.getText(),category.getText(),tags.getText()))refresh();};load.onClick=[this]{if(selected>=0&&selected<getNumRows())p.loadPresetFile(visible[selected].file);};preview.onClick=[this]{if(selected>=0&&selected<getNumRows())p.previewPersonal(visible[selected].file,pattern.getSelectedItemIndex());};stop.onClick=[this]{p.stopReference();};close.onClick=[this]{p.stopReference();if(onClose)onClose();};refreshButton.onClick=[this]{refresh();};favourite.onClick=[this]{if(selected<0||selected>=getNumRows())return;auto e=visible[selected];e.favourite=!e.favourite;if(writeLibraryInfo(e))refresh();else p.say("No se pudo guardar el favorito.");};import.onClick=[this]{choose(true);};exportFile.onClick=[this]{if(selected>=0&&selected<getNumRows())choose(false);};for(auto* c:std::initializer_list<juce::Component*>{&favourites,&pattern,&save,&load,&preview,&stop,&favourite,&import,&exportFile,&close,&refreshButton})c->setWantsKeyboardFocus(false);}
